<script setup>
import {computed,ref} from 'vue';
import {router,useForm,usePage} from '@inertiajs/vue3';
import PortalLayout from '@/Layouts/PortalLayout.vue';
const props=defineProps({coupons:Object,courses:Array,testSeries:Array});
const page=usePage();const hi=computed(()=>page.props.locale==='hi');
const editing=ref(null);
const blank=()=>({code:'',discount_type:'percentage',discount_value:10,minimum_amount:0,maximum_discount:'',usage_limit:'',per_user_limit:'',starts_at:'',ends_at:'',applies_to:'all',course_id:'',test_series_id:'',is_active:true});
const form=useForm(blank());
function reset(){editing.value=null;form.reset();form.clearErrors();}
function edit(c){editing.value=c.id;Object.assign(form,{code:c.code,discount_type:c.discount_type,discount_value:Number(c.discount_value),minimum_amount:Number(c.minimum_amount||0),maximum_discount:c.maximum_discount||'',usage_limit:c.usage_limit||'',per_user_limit:c.per_user_limit||'',starts_at:c.starts_at?c.starts_at.replace(' ','T').slice(0,16):'',ends_at:c.ends_at?c.ends_at.replace(' ','T').slice(0,16):'',applies_to:c.applies_to,course_id:c.course_id||'',test_series_id:c.test_series_id||'',is_active:c.is_active});}
function submit(){const payload={...form.data(),starts_at:form.starts_at||null,ends_at:form.ends_at||null,maximum_discount:form.maximum_discount||null,usage_limit:form.usage_limit||null,per_user_limit:form.per_user_limit||null,course_id:form.course_id||null,test_series_id:form.test_series_id||null};form.transform(()=>payload);editing.value?form.put('/admin/coupons/'+editing.value,{preserveScroll:true,onSuccess:reset}):form.post('/admin/coupons',{preserveScroll:true,onSuccess:reset});}
function remove(c){if(confirm('Delete coupon '+c.code+'? Coupons with redemptions must be deactivated.'))router.delete('/admin/coupons/'+c.id,{preserveScroll:true});}
</script>
<template><PortalLayout portal="admin" :title="hi?'कूपन प्रबंधन':'Coupon management'" subtitle="Create and manage checkout discount codes.">
<div class="grid gap-6 xl:grid-cols-[minmax(0,1fr)_380px]">
<section class="space-y-3"><div class="overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="p-3">Code</th><th class="p-3">Discount</th><th class="p-3">Scope</th><th class="p-3">Usage</th><th class="p-3">Status</th><th class="p-3">Actions</th></tr></thead><tbody><tr v-for="c in coupons.data" :key="c.id" class="border-t"><td class="p-3 font-bold">{{c.code}}</td><td class="p-3">{{c.discount_type==='percentage'?c.discount_value+'%':'₹'+c.discount_value}}</td><td class="p-3">{{c.applies_to==='course'?c.course?.title:c.applies_to==='test_series'?c.test_series?.title:'All items'}}</td><td class="p-3">{{c.used_count}}{{c.usage_limit?' / '+c.usage_limit:''}} ({{c.redemptions_count}})</td><td class="p-3">{{c.is_active?'Active':'Inactive'}}</td><td class="p-3 whitespace-nowrap"><button @click="edit(c)" class="mr-3 text-indigo-700">Edit</button><button @click="remove(c)" class="text-rose-700">Delete</button></td></tr><tr v-if="!coupons.data.length"><td colspan="6" class="p-8 text-center text-slate-500">No coupons created.</td></tr></tbody></table></div></section>
<aside class="h-fit rounded-xl border bg-white p-5"><h2 class="font-extrabold text-lg">{{editing?'Edit coupon':'Create coupon'}}</h2><form @submit.prevent="submit" class="mt-4 space-y-3">
<label class="block text-sm font-semibold">Coupon code<input v-model="form.code" required maxlength="40" class="mt-1 w-full rounded-lg border p-2 uppercase"/></label>
<div class="grid grid-cols-2 gap-2"><label class="text-sm font-semibold">Type<select v-model="form.discount_type" class="mt-1 w-full rounded-lg border p-2"><option value="percentage">Percentage</option><option value="fixed">Fixed amount</option></select></label><label class="text-sm font-semibold">Value<input v-model.number="form.discount_value" type="number" min="0.01" step="0.01" required class="mt-1 w-full rounded-lg border p-2"/></label></div>
<label class="block text-sm font-semibold">Minimum purchase (₹)<input v-model.number="form.minimum_amount" type="number" min="0" step="0.01" class="mt-1 w-full rounded-lg border p-2"/></label>
<label class="block text-sm font-semibold">Maximum discount (₹)<input v-model="form.maximum_discount" type="number" min="0.01" step="0.01" class="mt-1 w-full rounded-lg border p-2" placeholder="Optional"/></label>
<div class="grid grid-cols-2 gap-2"><label class="text-sm font-semibold">Total usage limit<input v-model="form.usage_limit" type="number" min="1" class="mt-1 w-full rounded-lg border p-2" placeholder="Unlimited"/></label><label class="text-sm font-semibold">Per student limit<input v-model="form.per_user_limit" type="number" min="1" class="mt-1 w-full rounded-lg border p-2" placeholder="Unlimited"/></label></div>
<label class="block text-sm font-semibold">Applies to<select v-model="form.applies_to" class="mt-1 w-full rounded-lg border p-2"><option value="all">All items</option><option value="course">Specific course</option><option value="test_series">Specific test series</option></select></label>
<label v-if="form.applies_to==='course'" class="block text-sm font-semibold">Course<select v-model="form.course_id" required class="mt-1 w-full rounded-lg border p-2"><option value="">Select course</option><option v-for="c in courses" :key="c.id" :value="c.id">{{c.title}}</option></select></label>
<label v-if="form.applies_to==='test_series'" class="block text-sm font-semibold">Test series<select v-model="form.test_series_id" required class="mt-1 w-full rounded-lg border p-2"><option value="">Select series</option><option v-for="s in testSeries" :key="s.id" :value="s.id">{{s.title}}</option></select></label>
<div class="grid grid-cols-2 gap-2"><label class="text-sm font-semibold">Starts at<input v-model="form.starts_at" type="datetime-local" class="mt-1 w-full rounded-lg border p-2"/></label><label class="text-sm font-semibold">Ends at<input v-model="form.ends_at" type="datetime-local" class="mt-1 w-full rounded-lg border p-2"/></label></div>
<label class="flex items-center gap-2 text-sm"><input v-model="form.is_active" type="checkbox"/> Active</label>
<div v-if="Object.keys(form.errors).length" class="text-xs text-rose-600">{{Object.values(form.errors).join(' ')}}</div>
<div class="flex gap-2"><button :disabled="form.processing" class="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-bold text-white disabled:opacity-50">{{form.processing?'Saving…':editing?'Update coupon':'Create coupon'}}</button><button v-if="editing" type="button" @click="reset" class="rounded-lg border px-4 py-2 text-sm">Cancel</button></div>
</form></aside></div></PortalLayout></template>
